<script setup>
import {ref,reactive,onMounted} from 'vue'
import {useAuthStore} from '../stores/auth.js'
const auth=useAuthStore(),rules=ref([]),error=ref(''),note=ref(''),busy=ref(false),form=reactive({metric:'heartRate',comparator:'gte',threshold:null,severity:'warning'})
async function load(){rules.value=(await auth.request('/api/operations/rules',undefined,'GET')).data}
async function act(fn){busy.value=true;error.value='';try{await fn();await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onMounted(()=>act(async()=>{}))
</script>
<template><section><h2>Reviewed hardware rules</h2><p>No thresholds are enabled by default. Internal review records approval; it does not certify a rule as medically or mine-safety valid. Simulator packets do not trigger these rules.</p><p v-if="error" role="alert">{{error}}</p><form v-if="auth.user?.role==='ADMIN'" @submit.prevent="act(()=>auth.request('/api/operations/rules',{...form}))"><select v-model="form.metric"><option v-for="m in ['heartRate','spo2','temperature','battery']" :key="m">{{m}}</option></select><select v-model="form.comparator"><option value="gte">At least</option><option value="lte">At most</option></select><label>Threshold in metric units<input v-model.number="form.threshold" type="number" step="any" required></label><select v-model="form.severity"><option>warning</option><option>critical</option></select><button :disabled="busy">Create disabled rule</button><label>Review note required to change enabled state<input v-model="note" maxlength="1000"></label></form><article v-for="r in rules" :key="r.id" class="management-record"><p>{{r.metric}} {{r.comparator}} {{r.threshold}} · {{r.severity}} · {{r.enabled?'Enabled':'Disabled'}} · {{r.reviewNote??'Not reviewed'}}</p><button v-if="auth.user?.role==='ADMIN'" :disabled="busy||!note.trim()" @click="act(()=>auth.request(`/api/operations/rules/${r.id}/review`,{enabled:!r.enabled,note}))">{{r.enabled?'Disable':'Approve and enable'}}</button></article></section></template>
